import java.nio.file.*;import java.sql.*;import java.util.*;import java.lang.reflect.*;import java.lang.management.*;import com.alibaba.fastjson2.*;import webridge.wbridge.storedprocedure.SPConfig;import webridge.wbridge.storedprocedure.invocation.SPInvokeManager;
public class WarmTiming {
 static boolean active=false,optimized=false;static String api;static JSONObject input;static boolean hit;
 static Map<String,Long> status(Connection c)throws Exception{Map<String,Long>m=new TreeMap<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SHOW SESSION STATUS WHERE Variable_name IN('Questions','Queries','Com_call_procedure','Com_select','Handler_read_key','Handler_read_next','Handler_read_rnd_next','Bytes_received','Bytes_sent')")){while(r.next())m.put(r.getString(1),r.getLong(2));}return m;}
 static Object value(Class<?>c,String n)throws Exception{Field f=c.getDeclaredField(n);f.setAccessible(true);return f.get(null);}static void set(Class<?>c,String n,Object v)throws Exception{Field f=c.getDeclaredField(n);f.setAccessible(true);f.set(null,v);}
 public static void main(String[]a)throws Exception{
 Path alignment=Paths.get(a[0]),home=Paths.get(a[1]),out=Paths.get(a[2]);String variant=a[3],db=a[4];int warm=Integer.parseInt(a[5]),measure=Integer.parseInt(a[6]);Files.createDirectory(out);input=JSON.parseArray(new String(Files.readAllBytes(alignment.resolve("graph-fixture/inputs.json")),"UTF-8")).getJSONObject(0);api=JSON.parseObject(new String(Files.readAllBytes(home.resolve("metadata.json")),"UTF-8")).getString("api");
 Class<?> model=Class.forName(variant.equals("full")?"RegionCompatibleAlignedIc5":"RegionCompatiblePrunedIc5");model.getMethod("configure",Path.class).invoke(null,alignment);String url=((String)value(model,"url")).replace("/jac_alignment?","/"+db+"?");url=url.replace("127.0.0.1:55337",System.getProperty("experiment.mysql.endpoint","127.0.0.1:18537"));SPConfig.addConfig(home.resolve("aligned.conf").toFile());System.setProperty("spDefDir",home.resolve("generated/sql").toString());
 Field boundary=model.getDeclaredField("regionBoundary");boundary.setAccessible(true);Class<?>type=boundary.getType();boundary.set(null,Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(proxy,method,args)->{if(method.getName().equals("enter")){if(optimized){SPInvokeManager.beginApi(api);active=true;SPInvokeManager.setInvokingSp(true);AlignedWeBridge.paramBuffer(input);}}else if(method.getName().equals("leave")&&active){hit=SPInvokeManager.isInvokingSp();SPInvokeManager.endApi();active=false;}return null;}));
 ThreadMXBean bean=ManagementFactory.getThreadMXBean();if(bean.isCurrentThreadCpuTimeSupported()&&!bean.isThreadCpuTimeEnabled())bean.setThreadCpuTimeEnabled(true);Files.write(out.resolve("cpu-timer.json"),("{\"supported\":"+bean.isCurrentThreadCpuTimeSupported()+",\"enabled\":"+bean.isThreadCpuTimeEnabled()+"}").getBytes("UTF-8"));List<JSONObject>rows=new ArrayList<>();try(Connection c=DriverManager.getConnection(url,"root","")){long conn=((Number)c.getClass().getMethod("getId").invoke(c)).longValue();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID=CONNECTION_ID()")){r.next();Files.write(out.resolve("connection.json"),("{\"connection_id\":"+conn+",\"pfs_thread_id\":"+r.getLong(1)+"}").getBytes("UTF-8"));}
 for(String phase:a[7].split(",")){optimized=phase.equals("sp");for(int i=0;i<warm+measure;i++){Map<String,Long>before=status(c);set(model,"calls",0L);((Map)value(model,"kinds")).clear();hit=false;long cpu=bean.getCurrentThreadCpuTime(),start=System.nanoTime();Object result=model.getMethod("request",Connection.class,JSONObject.class).invoke(null,c,input);double ms=(System.nanoTime()-start)/1e6,cpuMs=(bean.getCurrentThreadCpuTime()-cpu)/1e6;Map<String,Long>after=status(c);JSONObject row=new JSONObject();row.put("phase",phase);row.put("warmup",i<warm);row.put("iteration",i);row.put("ms",ms);row.put("thread_cpu_ms",cpuMs);row.put("jdbc_calls",value(model,"calls"));Map<String,Long>delta=new TreeMap<>();for(String k:after.keySet())delta.put(k,after.get(k)-before.get(k));row.put("status_delta",delta);row.put("questions",delta.get("Questions")-1);row.put("sp_enabled_at_end",hit);row.put("result",result);boolean ok=JSON.toJSONString(result).equals(input.getJSONArray("expected").toJSONString());row.put("oracle_ok",ok);rows.add(row);Files.write(out.resolve("rows.jsonl"),(row.toJSONString()+"\n").getBytes("UTF-8"),StandardOpenOption.CREATE,StandardOpenOption.APPEND);if(!ok||(optimized&&!hit)||delta.get("Com_call_procedure")!=(optimized?1L:0L))throw new IllegalStateException("Parity/SP activation failed");}}}
 Files.write(out.resolve("completed.json"),("{\"requests\":"+rows.size()+",\"variant\":\""+variant+"\",\"database\":\""+db+"\"}").getBytes("UTF-8"));System.exit(0);
 }
}
